#!/usr/bin/env node
// Panic Pantry — automated cross-platform multiplayer match.
//
// Orchestrates one authoritative server, a web client (Playwright/Chromium),
// the iOS Simulator build (xcrun simctl), the Android emulator build (adb) and
// the native macOS app. All clients auto-join the same room; the match is
// driven by a deterministic input script generated by `server/bin/plan.dart`
// and replayed through the server's test-input channel, so the final score is
// known in advance and must be reported identically by every client.
//
// Configuration is taken from the environment (see multiplayer-e2e.sh).

import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { env, makeHttp, parkMouse, placeWindow as moveWindow, serveWeb, sh, sleep, stamp, waitFor, windowBounds } from '../lib/common.mjs';

const here = fileURLToPath(new URL('.', import.meta.url));
const root = resolve(here, '..', '..');
const appDir = join(root, 'app');
const serverDir = join(root, 'server');

const PLATFORMS = env('PP_PLATFORMS', 'web ios android macos').split(/\s+/).filter(Boolean);
const OPTIONAL = new Set(env('PP_OPTIONAL_PLATFORMS', '').split(/\s+/).filter(Boolean));
const ROOM = env('PP_ROOM', 'E2E4').toUpperCase();
const SEED = Number(env('PP_SEED', '23'));
const LEVEL = env('PP_LEVEL', 'corner-cafe');
const SPEED = Number(env('PP_SPEED', '1'));
const PORT = Number(env('PP_PORT', '8787'));
const WEB_PORT = Number(env('PP_WEB_PORT', '8080'));
const OUT = resolve(env('PP_EVIDENCE_DIR', join(root, '.devin', 'clone-this', 'panic-pantry', 'evidence', 'e2e', stamp())));
const IOS_UDID = env('PP_IOS_UDID', '');
const ANDROID_AVD = env('PP_ANDROID_AVD', 'panic_pantry');
const ANDROID_SERIAL = env('PP_ANDROID_SERIAL', '');
const ANDROID_SERVER = env('PP_ANDROID_SERVER', `ws://10.0.2.2:${env('PP_PORT', '8787')}/ws`);
const ANDROID_WINDOW = env('PP_ANDROID_WINDOW', 'qemu-system-aarch64');
const ANDROID_SDK = env('ANDROID_SDK_ROOT', env('ANDROID_HOME', join(process.env.HOME, 'Library', 'Android', 'sdk')));
const ADB = join(ANDROID_SDK, 'platform-tools', 'adb');
const EMULATOR = join(ANDROID_SDK, 'emulator', 'emulator');
const JOIN_TIMEOUT = Number(env('PP_JOIN_TIMEOUT', '150')) * 1000;
const RECORD = env('PP_RECORD', '1') === '1';
const IOS_BUNDLE = 'dev.panicpantry.panicPantry';
const ANDROID_PKG = 'dev.panicpantry.panic_pantry';
const NAMES = { web: 'Webby', ios: 'Pip', android: 'Andi', macos: 'Mac' };
const WS_URL = `ws://localhost:${PORT}/ws`;

mkdirSync(OUT, { recursive: true });
const logFile = join(OUT, 'e2e.log');
const started = Date.now();
const lines = [];
function log(msg) {
  const line = `[${((Date.now() - started) / 1000).toFixed(1).padStart(6)}s] ${msg}`;
  lines.push(line);
  console.log(line);
  writeFileSync(logFile, lines.join('\n') + '\n');
}
const http = makeHttp(PORT);

const children = [];
function child(name, cmd, args, opts = {}) {
  const p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'], ...opts });
  const out = [];
  const push = (d) => {
    out.push(d.toString());
    writeFileSync(join(OUT, `${name}.log`), out.join(''));
  };
  p.stdout.on('data', push);
  p.stderr.on('data', push);
  p.on('exit', (code) => log(`${name} exited (${code})`));
  children.push({ name, p });
  return p;
}

// --- Platform launchers -----------------------------------------------------
const clientEnv = (name) => ({ PP_SERVER: WS_URL, PP_ROOM: ROOM, PP_NAME: name, PP_AUTO: '1' });

const shots = {}; // platform -> { phase -> path }
async function screenshot(platform, phase) {
  const file = join(OUT, `${platform}-${phase}.png`);
  try {
    switch (platform) {
      case 'web':
        await web.page.screenshot({ path: file });
        break;
      case 'ios':
        sh('xcrun', ['simctl', 'io', ios.udid, 'screenshot', file]);
        break;
      case 'android': {
        const r = sh(ADB, [...adbTarget(), 'exec-out', 'screencap', '-p'], { encoding: 'buffer', maxBuffer: 64 << 20 });
        writeFileSync(file, r.stdout);
        break;
      }
      case 'macos': {
        const b = macWindowBounds();
        sh('screencapture', ['-x', '-o', '-R', `${b.x},${b.y},${b.w},${b.h}`, file]);
        break;
      }
    }
    (shots[platform] ??= {})[phase] = file;
    log(`screenshot ${platform}/${phase} -> ${file}`);
  } catch (e) {
    log(`screenshot ${platform}/${phase} FAILED: ${e.message}`);
  }
}
const macWindowBounds = () => windowBounds('Panic Pantry');
function placeWindow(processName, x, y, w, h) {
  try {
    moveWindow(processName, x, y, w, h);
    parkMouse();
  } catch (e) {
    log(`could not place ${processName} window: ${e.message}`);
  }
}

const web = {};
async function launchWeb() {
  const { chromium } = await import('playwright');
  web.browser = await chromium.launch({
    headless: false,
    args: ['--window-position=0,0', '--window-size=800,600', '--autoplay-policy=no-user-gesture-required'],
  });
  web.context = await web.browser.newContext({ viewport: { width: 800, height: 520 } });
  web.page = await web.context.newPage();
  const consoleLog = [];
  web.page.on('console', (m) => {
    consoleLog.push(`[${m.type()}] ${m.text()}`);
    writeFileSync(join(OUT, 'web-console.log'), consoleLog.join('\n'));
  });
  const q = new URLSearchParams({ server: WS_URL, room: ROOM, name: NAMES.web, auto: '1' });
  await web.page.goto(`http://127.0.0.1:${WEB_PORT}/?${q}`, { waitUntil: 'load' });
  log('web client opened');
}

const ios = { udid: IOS_UDID };
async function launchIos() {
  if (!ios.udid) {
    const list = JSON.parse(sh('xcrun', ['simctl', 'list', 'devices', 'available', '-j']).stdout);
    const devices = Object.values(list.devices).flat();
    const pick = devices.find((d) => d.state === 'Booted') ?? devices.find((d) => /iPhone/.test(d.name));
    if (!pick) throw new Error('no iOS simulator available');
    ios.udid = pick.udid;
  }
  const app = join(appDir, 'build', 'ios', 'iphonesimulator', 'Runner.app');
  if (!existsSync(app)) throw new Error(`missing iOS build at ${app}`);
  sh('xcrun', ['simctl', 'boot', ios.udid]); // no-op when already booted
  sh('open', ['-a', 'Simulator']);
  await waitFor('simulator boot', () => sh('xcrun', ['simctl', 'bootstatus', ios.udid, '-b']).status === 0, 120000, 2000);
  sh('xcrun', ['simctl', 'terminate', ios.udid, IOS_BUNDLE]);
  const inst = sh('xcrun', ['simctl', 'install', ios.udid, app]);
  if (inst.status !== 0) throw new Error(`simctl install failed: ${inst.stderr}`);
  const e = { ...process.env };
  for (const [k, v] of Object.entries(clientEnv(NAMES.ios))) e[`SIMCTL_CHILD_${k}`] = v;
  const r = sh('xcrun', ['simctl', 'launch', ios.udid, IOS_BUNDLE], { env: e });
  if (r.status !== 0) throw new Error(`simctl launch failed: ${r.stderr}`);
  log(`ios client launched on ${ios.udid}: ${r.stdout.trim()}`);
  await sleep(1000);
  placeWindow('Simulator', 0, 560);
}

const android = {};
const adbTarget = () => (ANDROID_SERIAL ? ['-s', ANDROID_SERIAL] : []);
async function launchAndroid() {
  const apkDir = join(appDir, 'build', 'app', 'outputs', 'flutter-apk');
  const apk = ['app-release.apk', 'app-debug.apk'].map((f) => join(apkDir, f)).find(existsSync);
  if (!apk) throw new Error(`missing Android build in ${apkDir}`);
  if (!existsSync(ADB)) throw new Error(`adb not found at ${ADB}`);
  const devices = () =>
    sh(ADB, ['devices'])
      .stdout.split('\n')
      .slice(1)
      .filter((l) => /\tdevice$/.test(l))
      .filter((l) => !ANDROID_SERIAL || l.startsWith(ANDROID_SERIAL));
  if (devices().length === 0 && ANDROID_SERIAL.includes(':')) sh(ADB, ['connect', ANDROID_SERIAL]);
  if (devices().length === 0) {
    if (!existsSync(EMULATOR)) throw new Error(`emulator not found at ${EMULATOR}`);
    android.emu = child('android-emulator', EMULATOR, ['-avd', ANDROID_AVD, '-no-snapshot', '-no-boot-anim', '-no-audio']);
    await waitFor(
      'android emulator boot',
      () => {
        if (android.emu.exitCode !== null) throw new Error(`emulator exited (${android.emu.exitCode})`);
        return devices().length > 0 && sh(ADB, [...adbTarget(), 'shell', 'getprop', 'sys.boot_completed']).stdout.trim() === '1';
      },
      180000,
      3000,
    );
  }
  const inst = sh(ADB, [...adbTarget(), 'install', '-r', apk]);
  if (inst.status !== 0) throw new Error(`adb install failed: ${inst.stderr || inst.stdout}`);
  sh(ADB, [...adbTarget(), 'shell', 'am', 'force-stop', ANDROID_PKG]);
  sh(ADB, [...adbTarget(), 'shell', 'input', 'keyevent', 'KEYCODE_WAKEUP']);
  sh(ADB, [...adbTarget(), 'shell', 'wm', 'dismiss-keyguard']);
  sh(ADB, [...adbTarget(), 'shell', 'svc', 'power', 'stayon', 'true']);
  // MainActivity forwards PP_* intent extras to Dart through the `panic_pantry/launch` channel.
  const extras = Object.entries({ ...clientEnv(NAMES.android), PP_SERVER: ANDROID_SERVER }).flatMap(([k, v]) => ['--es', k, v]);
  const r = sh(ADB, [...adbTarget(), 'shell', 'am', 'start', '-W', '-n', `${ANDROID_PKG}/.MainActivity`, ...extras]);
  if (r.status !== 0) throw new Error(`am start failed: ${r.stderr || r.stdout}`);
  log('android client launched');
  placeWindow(ANDROID_WINDOW, 470, 560);
}

const mac = {};
async function launchMac() {
  const bin = join(appDir, 'build', 'macos', 'Build', 'Products', 'Debug', 'Panic Pantry.app', 'Contents', 'MacOS', 'Panic Pantry');
  if (!existsSync(bin)) throw new Error(`missing macOS build at ${bin}`);
  sh('pkill', ['-x', 'Panic Pantry']);
  await sleep(300);
  mac.proc = child('macos', bin, [], { env: { ...process.env, ...clientEnv(NAMES.macos) } });
  await waitFor('macOS window', () => macWindowBounds().w > 0, 30000, 500);
  // Right-middle keeps the window clear of notification banners and the Dock.
  placeWindow('Panic Pantry', 800, 560, 800, 540);
  log('macos client launched');
}

const launchers = { web: launchWeb, ios: launchIos, android: launchAndroid, macos: launchMac };

// --- Recording ----------------------------------------------------------------
let recorder;
function startRecording() {
  if (!RECORD) return;
  const file = join(OUT, 'four-way-match.mov');
  recorder = spawn('screencapture', ['-v', '-x', file], { stdio: 'ignore' });
  log(`screen recording -> ${file}`);
}
async function stopRecording() {
  if (!recorder) return;
  recorder.kill('SIGINT');
  await new Promise((r) => recorder.on('exit', r));
  recorder = undefined;
}

// --- Main -----------------------------------------------------------------------
const summary = {
  room: ROOM,
  seed: SEED,
  level: LEVEL,
  speed: SPEED,
  requested: PLATFORMS,
  joined: [],
  missing: {},
  screenshots: shots,
  evidenceDir: OUT,
  startedAt: new Date().toISOString(),
};
let failed = false;
let webServer;

async function cleanup() {
  await stopRecording();
  try {
    await web.browser?.close();
  } catch {}
  if (ios.udid) sh('xcrun', ['simctl', 'terminate', ios.udid, IOS_BUNDLE]);
  if (existsSync(ADB)) sh(ADB, [...adbTarget(), 'shell', 'am', 'force-stop', ANDROID_PKG]);
  for (const { p } of children.reverse()) {
    try {
      p.kill('SIGINT');
    } catch {}
  }
  webServer?.close();
}

process.on('SIGINT', async () => {
  log('interrupted');
  await cleanup();
  process.exit(130);
});

try {
  // 1. Server + web hosting.
  child('server', 'dart', ['run', 'bin/server.dart', '--port', String(PORT), '--test-harness'], { cwd: serverDir });
  await waitFor('server /health', async () => (await http('GET', '/health')).ok, 60000);
  log(`server ready on :${PORT}`);
  if (PLATFORMS.includes('web')) {
    webServer = await serveWeb(join(appDir, 'build', 'web'), WEB_PORT);
    log(`web build served on :${WEB_PORT}`);
  }

  // 2. Room with a fixed code, seed and level.
  await http('POST', '/test/rooms', { code: ROOM, seed: SEED, level: LEVEL, speed: SPEED });
  log(`room ${ROOM} created (seed ${SEED}, level ${LEVEL}, speed ${SPEED})`);

  // 3. Launch every client; optional platforms may fail without failing the run.
  startRecording();
  for (const platform of PLATFORMS) {
    try {
      await launchers[platform]();
    } catch (e) {
      if (OPTIONAL.has(platform)) {
        summary.missing[platform] = e.message;
        log(`OPTIONAL platform ${platform} unavailable: ${e.message}`);
      } else throw e;
    }
  }
  const expected = PLATFORMS.filter((p) => !summary.missing[p]);

  // 4. Wait for everyone to be in the lobby.
  const room = await waitFor(
    `${expected.join(', ')} to join ${ROOM}`,
    async () => {
      const r = await http('GET', `/test/rooms/${ROOM}`);
      const have = new Set(r.players.filter((p) => !p.bot && p.connected).map((p) => p.platform));
      const missing = expected.filter((p) => !have.has(p));
      if (missing.length) throw new Error(`still waiting for ${missing.join(', ')}`);
      return r;
    },
    JOIN_TIMEOUT,
    1000,
  );
  const humans = room.players.filter((p) => !p.bot);
  summary.joined = humans.map((p) => ({ platform: p.platform, name: p.name, slot: p.slot, id: p.id }));
  log(`lobby: ${humans.map((p) => `${p.name}(${p.platform}, slot ${p.slot})`).join(', ')}`);
  // Every client must answer a report before the match starts so that slow
  // (software-emulated) devices have finished their first frame.
  await http('POST', `/test/rooms/${ROOM}/players/*/command`, { cmd: 'report' });
  await waitFor(
    'lobby reports from every client',
    async () => {
      const r = await http('GET', `/test/rooms/${ROOM}`);
      return humans.every((p) => r.reports[p.id]?.phase === 'lobby') ? r : null;
    },
    JOIN_TIMEOUT,
    1000,
  );
  await sleep(1500);
  for (const p of humans) await screenshot(p.platform, 'lobby');

  // 5. Fill remaining seats with server bots, generate the deterministic plan.
  const botCount = 4 - humans.length;
  if (botCount > 0) {
    await http('POST', `/test/rooms/${ROOM}/bots`, { count: botCount });
    log(`added ${botCount} server bot(s)`);
  }
  const plan = sh('dart', ['run', 'bin/plan.dart', '--level', LEVEL, '--seed', String(SEED), '--match', '1', '--players', '4', '--scripted', humans.map((p) => p.slot).join(','), '--emotes'], {
    cwd: serverDir,
    maxBuffer: 256 << 20,
  });
  if (plan.status !== 0) throw new Error(`plan.dart failed: ${plan.stderr}`);
  const planJson = JSON.parse(plan.stdout);
  writeFileSync(join(OUT, 'plan.json'), JSON.stringify({ ...planJson, steps: undefined }, null, 2));
  summary.expected = planJson.expected;
  log(`plan: ${planJson.ticks} ticks, expected score ${planJson.expected.score}, ${planJson.expected.stars} star(s)`);
  for (const p of humans) {
    const r = await http('POST', `/test/rooms/${ROOM}/players/${p.id}/input`, { via: 'server', steps: planJson.steps[String(p.slot)] });
    log(`queued ${r.queued} scripted ticks for ${p.name}`);
  }

  // 6. Ready up through the client test channel and start the match.
  await http('POST', `/test/rooms/${ROOM}/players/*/command`, { cmd: 'ready', ready: true });
  await waitFor('everyone ready', async () => (await http('GET', `/test/rooms/${ROOM}`)).players.every((p) => p.ready), 15000);
  await http('POST', `/test/rooms/${ROOM}/start`);
  log('match started');

  // 7. Screenshots during play + mid-match consistency check.
  const roundSeconds = planJson.ticks * 0.05 / SPEED;
  await waitFor('gameplay', async () => (await http('GET', `/test/rooms/${ROOM}`)).phase === 'playing', 20000);
  await sleep(Math.min(20000, roundSeconds * 1000 * 0.3));
  for (const p of humans) await screenshot(p.platform, 'gameplay');
  await http('POST', `/test/rooms/${ROOM}/players/*/command`, { cmd: 'report' });
  const mid = await waitFor(
    'mid-match reports from every client',
    async () => {
      const r = await http('GET', `/test/rooms/${ROOM}`);
      return humans.every((p) => r.reports[p.id]?.phase === 'playing') ? r : null;
    },
    30000,
    1000,
  );
  summary.midMatch = Object.fromEntries(humans.map((p) => [p.platform, mid.reports[p.id]]));
  for (const p of humans) {
    const rep = mid.reports[p.id];
    log(`mid-match ${p.platform}: phase=${rep?.phase} tick=${rep?.tick} score=${rep?.score} rtt=${rep?.rtt}ms`);
    if (!rep || rep.phase !== 'playing') throw new Error(`${p.platform} did not report gameplay (${JSON.stringify(rep)})`);
  }
  await sleep(Math.min(25000, roundSeconds * 1000 * 0.3));
  for (const p of humans) await screenshot(p.platform, 'gameplay-late');

  // 8. Wait for the match to finish and compare results everywhere.
  const fin = await waitFor('match finished', async () => {
    const r = await http('GET', `/test/rooms/${ROOM}`);
    return r.phase === 'finished' && r.results ? r : null;
  }, roundSeconds * 1000 + 60000, 1000);
  await sleep(3500); // results screen count-up animation
  for (const p of humans) await screenshot(p.platform, 'results');
  await http('POST', `/test/rooms/${ROOM}/players/*/command`, { cmd: 'report' });
  const reports = await waitFor('results reports from every client', async () => {
    const r = await http('GET', `/test/rooms/${ROOM}`);
    const ok = humans.every((p) => r.reports[p.id]?.phase === 'finished' && r.reports[p.id]?.results);
    return ok ? r.reports : null;
  }, 20000, 500);

  const key = (res) => JSON.stringify({ score: res.score, stars: res.stars, served: res.served, tips: res.tips, expired: res.expired, bestCombo: res.bestCombo, wrongServes: res.wrongServes, burntPots: res.burntPots });
  const expectedKey = key(planJson.expected);
  const serverKey = key(fin.results);
  summary.results = {};
  const problems = [];
  for (const p of humans) {
    const rep = reports[p.id];
    summary.results[p.platform] = rep.results;
    const k = key(rep.results);
    log(`${p.platform.padEnd(7)} final: score=${rep.results.score} stars=${rep.results.stars} served=${rep.results.served} tips=${rep.results.tips} combo=${rep.results.bestCombo} screen=${rep.screen}`);
    if (k !== expectedKey) problems.push(`${p.platform} results ${k} != expected ${expectedKey}`);
    if (rep.screen !== 'results') problems.push(`${p.platform} is showing '${rep.screen}' instead of the results screen`);
  }
  if (serverKey !== expectedKey) problems.push(`server results ${serverKey} != expected ${expectedKey}`);
  const distinct = new Set(humans.map((p) => key(reports[p.id].results)));
  if (distinct.size !== 1) problems.push(`clients disagree: ${[...distinct].join(' | ')}`);
  summary.server = { ...fin.results, tick: fin.tick, phase: fin.phase };
  summary.problems = problems;
  summary.passed = problems.length === 0;
  summary.finishedAt = new Date().toISOString();
  if (problems.length) {
    failed = true;
    for (const p of problems) log(`ASSERTION FAILED: ${p}`);
  } else {
    log(`PASS: ${humans.length} client(s) [${humans.map((p) => p.platform).join(', ')}] + ${botCount} bot(s) agree: score ${planJson.expected.score}, ${planJson.expected.stars} star(s), served ${planJson.expected.served}`);
  }
  if (Object.keys(summary.missing).length) {
    log(`NOTE: platforms not exercised in this run: ${Object.keys(summary.missing).join(', ')}`);
  }
  await sleep(2000);
} catch (e) {
  failed = true;
  summary.error = e.message;
  log(`FAILED: ${e.stack || e.message}`);
} finally {
  writeFileSync(join(OUT, 'summary.json'), JSON.stringify(summary, null, 2));
  await cleanup();
  log(`evidence: ${OUT}`);
  process.exit(failed ? 1 : 0);
}
